insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('html-tableaux', 'html', 'Contenu', 'Tableaux de données', 'Présenter des données tabulaires avec des en-têtes qui restent compréhensibles.', '["table","thead","tbody","tr","th","td","caption","scope"]'::jsonb, 'Fondamental', '[{"type":"texte","titre":"Quand l’utiliser","contenu":"Un tableau sert à montrer des relations entre lignes et colonnes. Il ne doit pas servir à mettre une page en colonnes : CSS Grid et Flexbox existent pour la mise en page."},{"type":"code","titre":"Exemple accessible","langage":"HTML","contenu":"<table>\n  <caption>Méthodes HTTP courantes</caption>\n  <thead>\n    <tr><th scope=\"col\">Méthode</th><th scope=\"col\">Intention</th></tr>\n  </thead>\n  <tbody>\n    <tr><th scope=\"row\">GET</th><td>Lire une ressource</td></tr>\n    <tr><th scope=\"row\">POST</th><td>Créer ou déclencher une action</td></tr>\n  </tbody>\n</table>","legende":""},{"type":"alerte","variante":"retenir","titre":"À retenir","contenu":"caption nomme le tableau et scope indique si un th décrit une ligne ou une colonne. Ces relations sont essentielles quand le tableau est lu sans sa mise en page visuelle."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Tableaux HTML","url":"https://developer.mozilla.org/fr/docs/Learn_web_development/Core/Structuring_content/HTML_table_basics"}]},{"type":"texte","titre":"Explication approfondie","contenu":"HTML est le contrat de contenu de la page. Le navigateur, un lecteur d’écran et un moteur de recherche doivent comprendre la structure même si le CSS ou JavaScript ne se charge pas."},{"type":"liste","titre":"Concepts à retenir","contenu":["structure : cherchez où ce concept apparaît dans cette fiche avant de continuer.","sémantique : cherchez où ce concept apparaît dans cette fiche avant de continuer.","accessibilité : cherchez où ce concept apparaît dans cette fiche avant de continuer.","progressive enhancement : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Page éditoriale","HTML sémantique et titres logiques","Le contenu reste lisible, indexable et navigable au clavier."],["Application interactive","Commencer par une structure utilisable puis enrichir avec JavaScript","Une interface partiellement chargée reste compréhensible."],["Contenu utilisateur","Échapper et filtrer avant insertion","Le HTML ne devient pas un chemin d’injection."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"HTML","contenu":"<main>\n  <h1>Choisir une ressource</h1>\n  <form>\n    <label for=\"recherche\">Recherche</label>\n    <input id=\"recherche\" name=\"q\" type=\"search\">\n    <button type=\"submit\">Rechercher</button>\n  </form>\n</main>","legende":"Exercice : identifiez le rôle de chaque élément et testez le formulaire au clavier."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Tableaux de données », partez de un formulaire ou un contenu à structurer. Produisez un HTML sémantique navigable au clavier. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un champ vide ou une information absente. La décision à justifier est la suivante : choisir la balise selon le sens avant de penser au style."},{"type":"code","titre":"Mini-exercice spécifique : Tableaux de données","langage":"HTML","contenu":"<table>\n  <caption>Méthodes HTTP courantes</caption>\n  <thead>\n    <tr><th scope=\"col\">Méthode</th><th scope=\"col\">Intention</th></tr>\n  </thead>\n  <tbody>\n    <tr><th scope=\"row\">GET</th><td>Lire une ressource</td></tr>\n    <tr><th scope=\"row\">POST</th><td>Créer ou déclencher une action</td></tr>\n  </tbody>\n</table>","legende":"Leçon « Tableaux de données ». Entrée : un formulaire ou un contenu à structurer. Sortie attendue : un HTML sémantique navigable au clavier. Cas limite : un champ vide ou une information absente. Décision : choisir la balise selon le sens avant de penser au style."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Tableaux de données » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Revenez au sens du document : une structure lisible par une personne et une technologie d’assistance est plus solide qu’un empilement de div."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Tableaux de données » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Tableaux de données » et la reformuler avec vos mots.","concepts":["structure","sémantique"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Page éditoriale","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[1]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[10]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[16]}]'::jsonb, '["html-semantique","css-grid"]'::jsonb, 6);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('html-obsolete', 'html', 'Historique', 'Reconnaître le HTML obsolète', 'Identifier FONT, CENTER, BLINK, FRAMESET et les anciens attributs sans les reproduire.', '["font","center","blink","frameset","bgcolor","align","obsolete","historique"]'::jsonb, 'Historique', '[{"type":"texte","titre":"Pourquoi connaître ces syntaxes","contenu":"On les rencontre encore dans d’anciens sites, courriels ou supports pédagogiques. Elles mélangeaient contenu et présentation. Les navigateurs peuvent en tolérer certaines, mais elles ne constituent plus une méthode moderne."},{"type":"code","titre":"Ancien — à reconnaître seulement","langage":"HTML","contenu":"<font color=\"red\">Bonjour</font>\n<center>Titre centré</center>\n<body bgcolor=\"#ffffff\">\n<table align=\"center\">…</table>","legende":""},{"type":"code","titre":"Moderne — séparation HTML / CSS","langage":"HTML","contenu":"<p class=\"texte-alerte\">Bonjour</p>\n<h1 class=\"titre-centre\">Titre centré</h1>\n<table class=\"tableau-centre\">…</table>","legende":""},{"type":"code","titre":"Styles modernes","langage":"CSS","contenu":"body { background-color: #fff; }\n.texte-alerte { color: #c62828; }\n.titre-centre { text-align: center; }\n.tableau-centre { margin-inline: auto; }","legende":""},{"type":"comparaison","titre":"Correspondances pratiques","colonnes":["Ancien","Problème","Remplacement"],"lignes":[["<font>","Présentation dans le HTML","color, font-family en CSS"],["<center>, align","Alignement non sémantique","text-align, margin, Flexbox"],["bgcolor, background","Style de fond dans le HTML","background en CSS"],["<blink>","Non standard et gênant","Ne pas reproduire"],["<frameset>, <frame>","Document fragmenté et inaccessible","Mise en page normale ; iframe si intégration justifiée"]]},{"type":"alerte","variante":"obsolete","titre":"Obsolète","contenu":"Ne pas apprendre ces éléments comme solutions. Ils sont documentés uniquement pour lire et moderniser du code historique."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"WHATWG — Obsolete features","url":"https://html.spec.whatwg.org/multipage/obsolete.html"}]},{"type":"texte","titre":"Explication approfondie","contenu":"HTML est le contrat de contenu de la page. Le navigateur, un lecteur d’écran et un moteur de recherche doivent comprendre la structure même si le CSS ou JavaScript ne se charge pas."},{"type":"liste","titre":"Concepts à retenir","contenu":["structure : cherchez où ce concept apparaît dans cette fiche avant de continuer.","sémantique : cherchez où ce concept apparaît dans cette fiche avant de continuer.","accessibilité : cherchez où ce concept apparaît dans cette fiche avant de continuer.","progressive enhancement : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Page éditoriale","HTML sémantique et titres logiques","Le contenu reste lisible, indexable et navigable au clavier."],["Application interactive","Commencer par une structure utilisable puis enrichir avec JavaScript","Une interface partiellement chargée reste compréhensible."],["Contenu utilisateur","Échapper et filtrer avant insertion","Le HTML ne devient pas un chemin d’injection."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"HTML","contenu":"<main>\n  <h1>Choisir une ressource</h1>\n  <form>\n    <label for=\"recherche\">Recherche</label>\n    <input id=\"recherche\" name=\"q\" type=\"search\">\n    <button type=\"submit\">Rechercher</button>\n  </form>\n</main>","legende":"Exercice : identifiez le rôle de chaque élément et testez le formulaire au clavier."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Reconnaître le HTML obsolète », partez de un formulaire ou un contenu à structurer. Produisez un HTML sémantique navigable au clavier. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un champ vide ou une information absente. La décision à justifier est la suivante : choisir la balise selon le sens avant de penser au style."},{"type":"code","titre":"Mini-exercice spécifique : Reconnaître le HTML obsolète","langage":"HTML","contenu":"<font color=\"red\">Bonjour</font>\n<center>Titre centré</center>\n<body bgcolor=\"#ffffff\">\n<table align=\"center\">…</table>","legende":"Leçon « Reconnaître le HTML obsolète ». Entrée : un formulaire ou un contenu à structurer. Sortie attendue : un HTML sémantique navigable au clavier. Cas limite : un champ vide ou une information absente. Décision : choisir la balise selon le sens avant de penser au style."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Reconnaître le HTML obsolète » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Revenez au sens du document : une structure lisible par une personne et une technologie d’assistance est plus solide qu’un empilement de div."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Reconnaître le HTML obsolète » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Reconnaître le HTML obsolète » et la reformuler avec vos mots.","concepts":["structure","sémantique"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Page éditoriale","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[1]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[13]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[19]}]'::jsonb, '["html-document","css-selecteurs","css-flexbox"]'::jsonb, 7);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('css-selecteurs', 'css', 'Fondamentaux', 'Sélecteurs CSS et spécificité', 'Cibler des éléments et comprendre pourquoi une déclaration gagne dans la cascade.', '["sélecteur","cascade","spécificité","class","id","pseudo-classe"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Syntaxe","langage":"CSS","contenu":".carte {\n  border: 1px solid #334155;\n}\n\n.carte > h2 {\n  margin-block-start: 0;\n}\n\n.carte:hover {\n  border-color: #5eead4;\n}","legende":""},{"type":"decomposition","titre":"Anatomie d’une règle","elements":[{"terme":".carte","explication":"sélecteur : détermine quels éléments correspondent."},{"terme":"border","explication":"propriété à modifier."},{"terme":"1px solid #334155","explication":"valeur composée : largeur, style et couleur."},{"terme":":hover","explication":"pseudo-classe liée à un état d’interaction."}]},{"type":"texte","titre":"Comment la cascade tranche","contenu":"Le navigateur considère d’abord l’importance et l’origine des déclarations, puis la spécificité du sélecteur, puis l’ordre d’apparition si le reste est à égalité. Héritage et valeur initiale interviennent lorsqu’aucune déclaration directe ne gagne."},{"type":"alerte","variante":"bonne-pratique","titre":"Bonne pratique","contenu":"Préférer des classes courtes et prévisibles. Empiler des ids, des sélecteurs imbriqués et !important rend chaque évolution plus coûteuse."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Cascade et héritage","url":"https://developer.mozilla.org/fr/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts"}]},{"type":"texte","titre":"Explication approfondie","contenu":"CSS transforme une structure en interface. Une règle maintenable part d’un flux naturel, utilise des contraintes simples et ajoute les exceptions seulement quand le scénario les justifie."},{"type":"liste","titre":"Concepts à retenir","contenu":["cascade : cherchez où ce concept apparaît dans cette fiche avant de continuer.","box model : cherchez où ce concept apparaît dans cette fiche avant de continuer.","layout : cherchez où ce concept apparaît dans cette fiche avant de continuer.","responsive design : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Composant réutilisable","Propriétés locales et container query","Le composant réagit à son espace réel."],["Quelques tailles fixes","Media queries simples","Elles sont faciles à expliquer quand la fenêtre pilote la mise en page."],["Thème clair et sombre","Custom properties centralisées","Une décision visuelle se modifie sans réécrire les sélecteurs."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"CSS","contenu":":root { --espace: 1rem; --surface: #fff; --texte: #243447; }\n\n.carte {\n  display: grid;\n  gap: var(--espace);\n  color: var(--texte);\n  background: var(--surface);\n}","legende":"Exercice : redimensionnez la fenêtre puis remplacez une valeur du thème."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Sélecteurs CSS et spécificité », partez de un composant placé dans plusieurs largeurs. Produisez une mise en page lisible et responsive. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un texte long ou un conteneur très étroit. La décision à justifier est la suivante : préférer une contrainte simple avant d’ajouter une exception."},{"type":"code","titre":"Mini-exercice spécifique : Sélecteurs CSS et spécificité","langage":"CSS","contenu":".carte {\n  border: 1px solid #334155;\n}\n\n.carte > h2 {\n  margin-block-start: 0;\n}\n\n.carte:hover {\n  border-color: #5eead4;\n}","legende":"Leçon « Sélecteurs CSS et spécificité ». Entrée : un composant placé dans plusieurs largeurs. Sortie attendue : une mise en page lisible et responsive. Cas limite : un texte long ou un conteneur très étroit. Décision : préférer une contrainte simple avant d’ajouter une exception."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Sélecteurs CSS et spécificité » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Testez le composant dans une largeur étroite, une largeur large et avec le clavier : la mise en forme doit rester une conséquence de la structure."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Sélecteurs CSS et spécificité » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Sélecteurs CSS et spécificité » et la reformuler avec vos mots.","concepts":["cascade","box model"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Composant réutilisable","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["html-attributs","css-box-model","css-variables"]'::jsonb, 8);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('css-box-model', 'css', 'Mise en page', 'Modèle de boîte et box-sizing', 'Raisonner avec contenu, padding, bordure et marge pour expliquer les dimensions réelles.', '["box model","margin","padding","border","box-sizing","width"]'::jsonb, 'Fondamental', '[{"type":"texte","titre":"Fonctionnement interne","contenu":"Chaque élément génère une ou plusieurs boîtes. Par défaut, width vise seulement la zone de contenu ; padding et border s’ajoutent. Avec border-box, width inclut contenu, padding et bordure, ce qui simplifie les calculs."},{"type":"code","titre":"Réglage recommandé","langage":"CSS","contenu":"*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\n.carte {\n  width: 320px;\n  padding: 24px;\n  border: 1px solid;\n  margin-block: 16px;\n}","legende":""},{"type":"decomposition","titre":"Les quatre zones","elements":[{"terme":"content","explication":"texte, image ou enfants de la boîte."},{"terme":"padding","explication":"espace intérieur entre contenu et bordure."},{"terme":"border","explication":"limite dessinée autour du padding."},{"terme":"margin","explication":"espace extérieur ; les marges verticales de blocs peuvent fusionner."}]},{"type":"alerte","variante":"erreur","titre":"Pourquoi la boîte dépasse","contenu":"Avec content-box, width: 320px + deux paddings de 24px + deux bordures de 1px donne 370px. border-box maintient la largeur extérieure déclarée à 320px."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Le modèle de boîte","url":"https://developer.mozilla.org/fr/docs/Learn_web_development/Core/Styling_basics/Box_model"}]},{"type":"texte","titre":"Explication approfondie","contenu":"CSS transforme une structure en interface. Une règle maintenable part d’un flux naturel, utilise des contraintes simples et ajoute les exceptions seulement quand le scénario les justifie."},{"type":"liste","titre":"Concepts à retenir","contenu":["cascade : cherchez où ce concept apparaît dans cette fiche avant de continuer.","box model : cherchez où ce concept apparaît dans cette fiche avant de continuer.","layout : cherchez où ce concept apparaît dans cette fiche avant de continuer.","responsive design : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Composant réutilisable","Propriétés locales et container query","Le composant réagit à son espace réel."],["Quelques tailles fixes","Media queries simples","Elles sont faciles à expliquer quand la fenêtre pilote la mise en page."],["Thème clair et sombre","Custom properties centralisées","Une décision visuelle se modifie sans réécrire les sélecteurs."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"CSS","contenu":":root { --espace: 1rem; --surface: #fff; --texte: #243447; }\n\n.carte {\n  display: grid;\n  gap: var(--espace);\n  color: var(--texte);\n  background: var(--surface);\n}","legende":"Exercice : redimensionnez la fenêtre puis remplacez une valeur du thème."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Modèle de boîte et box-sizing », partez de un composant placé dans plusieurs largeurs. Produisez une mise en page lisible et responsive. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un texte long ou un conteneur très étroit. La décision à justifier est la suivante : préférer une contrainte simple avant d’ajouter une exception."},{"type":"code","titre":"Mini-exercice spécifique : Modèle de boîte et box-sizing","langage":"CSS","contenu":"*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\n.carte {\n  width: 320px;\n  padding: 24px;\n  border: 1px solid;\n  margin-block: 16px;\n}","legende":"Leçon « Modèle de boîte et box-sizing ». Entrée : un composant placé dans plusieurs largeurs. Sortie attendue : une mise en page lisible et responsive. Cas limite : un texte long ou un conteneur très étroit. Décision : préférer une contrainte simple avant d’ajouter une exception."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Modèle de boîte et box-sizing » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Testez le composant dans une largeur étroite, une largeur large et avec le clavier : la mise en forme doit rester une conséquence de la structure."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Modèle de boîte et box-sizing » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Modèle de boîte et box-sizing » et la reformuler avec vos mots.","concepts":["cascade","box model"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Composant réutilisable","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[1]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["css-selecteurs","css-flexbox","css-grid"]'::jsonb, 9);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('css-flexbox', 'css', 'Mise en page', 'Flexbox', 'Distribuer et aligner des éléments sur un axe principal, avec un axe secondaire.', '["display flex","justify-content","align-items","gap","flex-wrap"]'::jsonb, 'Fondamental', '[{"type":"texte","titre":"Quand l’utiliser","contenu":"Flexbox est excellent pour une barre d’actions, une navigation, un groupe de cartes sur une dimension ou le centrage d’un composant. Pour contrôler simultanément lignes et colonnes, Grid est souvent plus direct."},{"type":"code","titre":"Exemple responsive","langage":"CSS","contenu":".barre-actions {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1rem;\n  flex-wrap: wrap;\n}","legende":""},{"type":"decomposition","titre":"Axes et propriétés","elements":[{"terme":"flex-direction","explication":"définit l’axe principal : row par défaut, ou column."},{"terme":"justify-content","explication":"aligne ou distribue le long de l’axe principal."},{"terme":"align-items","explication":"aligne sur l’axe secondaire."},{"terme":"gap","explication":"espace cohérent entre les enfants sans marges compensatoires."},{"terme":"flex: 1","explication":"raccourci permettant notamment à un enfant d’occuper l’espace disponible."}]},{"type":"alerte","variante":"erreur","titre":"Erreur fréquente","contenu":"justify-content ne signifie pas toujours “horizontal”. Son axe dépend de flex-direction. Avec flex-direction: column, il agit verticalement."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Flexbox","url":"https://developer.mozilla.org/fr/docs/Learn_web_development/Core/CSS_layout/Flexbox"}]},{"type":"texte","titre":"Explication approfondie","contenu":"CSS transforme une structure en interface. Une règle maintenable part d’un flux naturel, utilise des contraintes simples et ajoute les exceptions seulement quand le scénario les justifie."},{"type":"liste","titre":"Concepts à retenir","contenu":["cascade : cherchez où ce concept apparaît dans cette fiche avant de continuer.","box model : cherchez où ce concept apparaît dans cette fiche avant de continuer.","layout : cherchez où ce concept apparaît dans cette fiche avant de continuer.","responsive design : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Composant réutilisable","Propriétés locales et container query","Le composant réagit à son espace réel."],["Quelques tailles fixes","Media queries simples","Elles sont faciles à expliquer quand la fenêtre pilote la mise en page."],["Thème clair et sombre","Custom properties centralisées","Une décision visuelle se modifie sans réécrire les sélecteurs."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"CSS","contenu":":root { --espace: 1rem; --surface: #fff; --texte: #243447; }\n\n.carte {\n  display: grid;\n  gap: var(--espace);\n  color: var(--texte);\n  background: var(--surface);\n}","legende":"Exercice : redimensionnez la fenêtre puis remplacez une valeur du thème."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Flexbox », partez de un composant placé dans plusieurs largeurs. Produisez une mise en page lisible et responsive. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un texte long ou un conteneur très étroit. La décision à justifier est la suivante : préférer une contrainte simple avant d’ajouter une exception."},{"type":"code","titre":"Mini-exercice spécifique : Flexbox","langage":"CSS","contenu":".barre-actions {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1rem;\n  flex-wrap: wrap;\n}","legende":"Leçon « Flexbox ». Entrée : un composant placé dans plusieurs largeurs. Sortie attendue : une mise en page lisible et responsive. Cas limite : un texte long ou un conteneur très étroit. Décision : préférer une contrainte simple avant d’ajouter une exception."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Flexbox » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Testez le composant dans une largeur étroite, une largeur large et avec le clavier : la mise en forme doit rester une conséquence de la structure."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Flexbox » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Flexbox » et la reformuler avec vos mots.","concepts":["cascade","box model"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Composant réutilisable","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[1]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["css-grid","css-box-model","css-responsive"]'::jsonb, 10);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('css-grid', 'css', 'Mise en page', 'CSS Grid', 'Définir une grille en deux dimensions et laisser les éléments s’y placer proprement.', '["display grid","grid-template-columns","minmax","fr","gap"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Grille fluide","langage":"CSS","contenu":".grille {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));\n  gap: 1rem;\n}","legende":""},{"type":"decomposition","titre":"Décomposition","elements":[{"terme":"repeat()","explication":"répète une définition de piste."},{"terme":"auto-fit","explication":"crée autant de colonnes que l’espace permet et replie les pistes vides."},{"terme":"minmax()","explication":"borne la largeur minimale et maximale d’une piste."},{"terme":"1fr","explication":"une fraction de l’espace disponible."},{"terme":"min(100%, 16rem)","explication":"évite qu’une largeur minimale fixe déborde sur un très petit écran."}]},{"type":"comparaison","titre":"Flexbox ou Grid ?","colonnes":["Besoin","Choix courant","Pourquoi"],"lignes":[["Aligner sur un axe","Flexbox","Distribution linéaire"],["Lignes et colonnes coordonnées","Grid","Contrôle bidimensionnel"],["Composants de largeur variable","Les deux","Le contenu décide souvent"],["Ordre logique","HTML d’abord","Ne pas réordonner au détriment du clavier"]]},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — CSS Grid","url":"https://developer.mozilla.org/fr/docs/Learn_web_development/Core/CSS_layout/Grids"}]},{"type":"texte","titre":"Explication approfondie","contenu":"CSS transforme une structure en interface. Une règle maintenable part d’un flux naturel, utilise des contraintes simples et ajoute les exceptions seulement quand le scénario les justifie."},{"type":"liste","titre":"Concepts à retenir","contenu":["cascade : cherchez où ce concept apparaît dans cette fiche avant de continuer.","box model : cherchez où ce concept apparaît dans cette fiche avant de continuer.","layout : cherchez où ce concept apparaît dans cette fiche avant de continuer.","responsive design : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Composant réutilisable","Propriétés locales et container query","Le composant réagit à son espace réel."],["Quelques tailles fixes","Media queries simples","Elles sont faciles à expliquer quand la fenêtre pilote la mise en page."],["Thème clair et sombre","Custom properties centralisées","Une décision visuelle se modifie sans réécrire les sélecteurs."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"CSS","contenu":":root { --espace: 1rem; --surface: #fff; --texte: #243447; }\n\n.carte {\n  display: grid;\n  gap: var(--espace);\n  color: var(--texte);\n  background: var(--surface);\n}","legende":"Exercice : redimensionnez la fenêtre puis remplacez une valeur du thème."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « CSS Grid », partez de un composant placé dans plusieurs largeurs. Produisez une mise en page lisible et responsive. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un texte long ou un conteneur très étroit. La décision à justifier est la suivante : préférer une contrainte simple avant d’ajouter une exception."},{"type":"code","titre":"Mini-exercice spécifique : CSS Grid","langage":"CSS","contenu":".grille {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));\n  gap: 1rem;\n}","legende":"Leçon « CSS Grid ». Entrée : un composant placé dans plusieurs largeurs. Sortie attendue : une mise en page lisible et responsive. Cas limite : un texte long ou un conteneur très étroit. Décision : préférer une contrainte simple avant d’ajouter une exception."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « CSS Grid » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Testez le composant dans une largeur étroite, une largeur large et avec le clavier : la mise en forme doit rester une conséquence de la structure."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « CSS Grid » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « CSS Grid » et la reformuler avec vos mots.","concepts":["cascade","box model"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Composant réutilisable","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[10]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[16]}]'::jsonb, '["css-flexbox","css-responsive","html-tableaux"]'::jsonb, 11);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('css-responsive', 'css', 'Responsive', 'Responsive design et media queries', 'Construire une mise en page fluide qui s’adapte au contenu, puis ajouter des points de rupture utiles.', '["responsive","media query","mobile first","clamp","viewport"]'::jsonb, 'Fondamental', '[{"type":"texte","titre":"Approche recommandée","contenu":"Commencer par une mise en page simple adaptée aux petits écrans, employer des unités et grilles fluides, puis introduire une media query quand le contenu ne respire plus. Un breakpoint répond à un problème de composition, pas à un modèle de téléphone."},{"type":"code","titre":"Exemple mobile-first","langage":"CSS","contenu":".contenu {\n  width: min(100% - 2rem, 72rem);\n  margin-inline: auto;\n}\n\n.titre {\n  font-size: clamp(2rem, 5vw, 4.5rem);\n}\n\n@media (min-width: 48rem) {\n  .mise-en-page {\n    display: grid;\n    grid-template-columns: 18rem 1fr;\n  }\n}","legende":""},{"type":"alerte","variante":"bonne-pratique","titre":"Tester le contenu","contenu":"Réduire la fenêtre progressivement : les mots longs, tableaux, blocs de code et menus révèlent mieux les vrais points de rupture qu’une liste d’appareils prédéfinis."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Responsive design","url":"https://developer.mozilla.org/fr/docs/Learn_web_development/Core/CSS_layout/Responsive_Design"}]},{"type":"texte","titre":"Explication approfondie","contenu":"CSS transforme une structure en interface. Une règle maintenable part d’un flux naturel, utilise des contraintes simples et ajoute les exceptions seulement quand le scénario les justifie."},{"type":"liste","titre":"Concepts à retenir","contenu":["cascade : cherchez où ce concept apparaît dans cette fiche avant de continuer.","box model : cherchez où ce concept apparaît dans cette fiche avant de continuer.","layout : cherchez où ce concept apparaît dans cette fiche avant de continuer.","responsive design : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Composant réutilisable","Propriétés locales et container query","Le composant réagit à son espace réel."],["Quelques tailles fixes","Media queries simples","Elles sont faciles à expliquer quand la fenêtre pilote la mise en page."],["Thème clair et sombre","Custom properties centralisées","Une décision visuelle se modifie sans réécrire les sélecteurs."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"CSS","contenu":":root { --espace: 1rem; --surface: #fff; --texte: #243447; }\n\n.carte {\n  display: grid;\n  gap: var(--espace);\n  color: var(--texte);\n  background: var(--surface);\n}","legende":"Exercice : redimensionnez la fenêtre puis remplacez une valeur du thème."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Responsive design et media queries », partez de un composant placé dans plusieurs largeurs. Produisez une mise en page lisible et responsive. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un texte long ou un conteneur très étroit. La décision à justifier est la suivante : préférer une contrainte simple avant d’ajouter une exception."},{"type":"code","titre":"Mini-exercice spécifique : Responsive design et media queries","langage":"CSS","contenu":".contenu {\n  width: min(100% - 2rem, 72rem);\n  margin-inline: auto;\n}\n\n.titre {\n  font-size: clamp(2rem, 5vw, 4.5rem);\n}\n\n@media (min-width: 48rem) {\n  .mise-en-page {\n    display: grid;\n    grid-template-columns: 18rem 1fr;\n  }\n}","legende":"Leçon « Responsive design et media queries ». Entrée : un composant placé dans plusieurs largeurs. Sortie attendue : une mise en page lisible et responsive. Cas limite : un texte long ou un conteneur très étroit. Décision : préférer une contrainte simple avant d’ajouter une exception."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Responsive design et media queries » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Testez le composant dans une largeur étroite, une largeur large et avec le clavier : la mise en forme doit rester une conséquence de la structure."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Responsive design et media queries » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Responsive design et media queries » et la reformuler avec vos mots.","concepts":["cascade","box model"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Composant réutilisable","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[1]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[10]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[16]}]'::jsonb, '["css-grid","css-flexbox","html-document"]'::jsonb, 12);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('css-variables', 'css', 'Architecture', 'Propriétés personnalisées CSS', 'Nommer et réutiliser des valeurs CSS tout en profitant de la cascade.', '["custom properties","var","root","design tokens","variables"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Syntaxe","langage":"CSS","contenu":":root {\n  --couleur-accent: #5eead4;\n  --espace-4: 1rem;\n}\n\n.bouton {\n  color: var(--couleur-accent);\n  padding: var(--espace-4);\n}\n\n.zone-danger {\n  --couleur-accent: #fb7185;\n}","legende":""},{"type":"texte","titre":"Fonctionnement","contenu":"Une propriété personnalisée appartient à un élément et est héritée par ses descendants. La valeur est résolue au moment où var() est utilisée, ce qui permet de modifier un thème ou un composant localement."},{"type":"decomposition","titre":"Décomposition","elements":[{"terme":"--couleur-accent","explication":"nom sensible à la casse, précédé de deux tirets."},{"terme":"var(--couleur-accent)","explication":"lit la valeur calculée dans le contexte de l’élément."},{"terme":"var(--inconnue, blue)","explication":"blue sert de valeur de repli si la propriété est absente ou invalide."}]},{"type":"alerte","variante":"attention","titre":"Ce n’est pas Sass","contenu":"Ces variables existent dans le navigateur, participent à la cascade et peuvent changer à l’exécution. Elles ne sont pas remplacées une fois pour toutes lors d’une compilation."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Propriétés personnalisées","url":"https://developer.mozilla.org/fr/docs/Web/CSS/Guides/Cascading_variables/Using_custom_properties"}]},{"type":"texte","titre":"Explication approfondie","contenu":"CSS transforme une structure en interface. Une règle maintenable part d’un flux naturel, utilise des contraintes simples et ajoute les exceptions seulement quand le scénario les justifie."},{"type":"liste","titre":"Concepts à retenir","contenu":["cascade : cherchez où ce concept apparaît dans cette fiche avant de continuer.","box model : cherchez où ce concept apparaît dans cette fiche avant de continuer.","layout : cherchez où ce concept apparaît dans cette fiche avant de continuer.","responsive design : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Composant réutilisable","Propriétés locales et container query","Le composant réagit à son espace réel."],["Quelques tailles fixes","Media queries simples","Elles sont faciles à expliquer quand la fenêtre pilote la mise en page."],["Thème clair et sombre","Custom properties centralisées","Une décision visuelle se modifie sans réécrire les sélecteurs."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"CSS","contenu":":root { --espace: 1rem; --surface: #fff; --texte: #243447; }\n\n.carte {\n  display: grid;\n  gap: var(--espace);\n  color: var(--texte);\n  background: var(--surface);\n}","legende":"Exercice : redimensionnez la fenêtre puis remplacez une valeur du thème."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Propriétés personnalisées CSS », partez de un composant placé dans plusieurs largeurs. Produisez une mise en page lisible et responsive. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un texte long ou un conteneur très étroit. La décision à justifier est la suivante : préférer une contrainte simple avant d’ajouter une exception."},{"type":"code","titre":"Mini-exercice spécifique : Propriétés personnalisées CSS","langage":"CSS","contenu":":root {\n  --couleur-accent: #5eead4;\n  --espace-4: 1rem;\n}\n\n.bouton {\n  color: var(--couleur-accent);\n  padding: var(--espace-4);\n}\n\n.zone-danger {\n  --couleur-accent: #fb7185;\n}","legende":"Leçon « Propriétés personnalisées CSS ». Entrée : un composant placé dans plusieurs largeurs. Sortie attendue : une mise en page lisible et responsive. Cas limite : un texte long ou un conteneur très étroit. Décision : préférer une contrainte simple avant d’ajouter une exception."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Propriétés personnalisées CSS » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Testez le composant dans une largeur étroite, une largeur large et avec le clavier : la mise en forme doit rester une conséquence de la structure."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Propriétés personnalisées CSS » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Propriétés personnalisées CSS » et la reformuler avec vos mots.","concepts":["cascade","box model"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Composant réutilisable","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["css-selecteurs","css-responsive","css-outils-comparaison"]'::jsonb, 13);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('css-typographie', 'css', 'Présentation', 'Typographie lisible en CSS', 'Régler taille, hauteur de ligne et largeur de lecture sans sacrifier l’accessibilité.', '["font","line-height","rem","ch","lisibilité"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Base raisonnable","langage":"CSS","contenu":"body {\n  font-family: system-ui, sans-serif;\n  font-size: 1rem;\n  line-height: 1.6;\n}\n\n.prose {\n  max-width: 68ch;\n}\n\nh1 {\n  font-size: clamp(2rem, 6vw, 4rem);\n  line-height: 1.05;\n}","legende":""},{"type":"liste","titre":"Repères","contenu":["rem suit généralement la taille de police racine et respecte les réglages utilisateur.","Une ligne de texte trop longue fatigue ; une largeur en ch borne approximativement le nombre de caractères.","line-height sans unité s’adapte aux tailles héritées.","Le contraste, les états de focus et le zoom à 200 % font partie de la lisibilité."]},{"type":"alerte","variante":"erreur","titre":"Erreur fréquente","contenu":"Désactiver le zoom ou figer toute la typographie en pixels pénalise les personnes qui adaptent leur affichage."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Mise en forme du texte","url":"https://developer.mozilla.org/fr/docs/Learn_web_development/Core/Text_styling/Fundamentals"}]},{"type":"texte","titre":"Explication approfondie","contenu":"CSS transforme une structure en interface. Une règle maintenable part d’un flux naturel, utilise des contraintes simples et ajoute les exceptions seulement quand le scénario les justifie."},{"type":"liste","titre":"Concepts à retenir","contenu":["cascade : cherchez où ce concept apparaît dans cette fiche avant de continuer.","box model : cherchez où ce concept apparaît dans cette fiche avant de continuer.","layout : cherchez où ce concept apparaît dans cette fiche avant de continuer.","responsive design : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Composant réutilisable","Propriétés locales et container query","Le composant réagit à son espace réel."],["Quelques tailles fixes","Media queries simples","Elles sont faciles à expliquer quand la fenêtre pilote la mise en page."],["Thème clair et sombre","Custom properties centralisées","Une décision visuelle se modifie sans réécrire les sélecteurs."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"CSS","contenu":":root { --espace: 1rem; --surface: #fff; --texte: #243447; }\n\n.carte {\n  display: grid;\n  gap: var(--espace);\n  color: var(--texte);\n  background: var(--surface);\n}","legende":"Exercice : redimensionnez la fenêtre puis remplacez une valeur du thème."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Typographie lisible en CSS », partez de un composant placé dans plusieurs largeurs. Produisez une mise en page lisible et responsive. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un texte long ou un conteneur très étroit. La décision à justifier est la suivante : préférer une contrainte simple avant d’ajouter une exception."},{"type":"code","titre":"Mini-exercice spécifique : Typographie lisible en CSS","langage":"CSS","contenu":"body {\n  font-family: system-ui, sans-serif;\n  font-size: 1rem;\n  line-height: 1.6;\n}\n\n.prose {\n  max-width: 68ch;\n}\n\nh1 {\n  font-size: clamp(2rem, 6vw, 4rem);\n  line-height: 1.05;\n}","legende":"Leçon « Typographie lisible en CSS ». Entrée : un composant placé dans plusieurs largeurs. Sortie attendue : une mise en page lisible et responsive. Cas limite : un texte long ou un conteneur très étroit. Décision : préférer une contrainte simple avant d’ajouter une exception."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Typographie lisible en CSS » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Testez le composant dans une largeur étroite, une largeur large et avec le clavier : la mise en forme doit rester une conséquence de la structure."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Typographie lisible en CSS » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Typographie lisible en CSS » et la reformuler avec vos mots.","concepts":["cascade","box model"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Composant réutilisable","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[10]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[16]}]'::jsonb, '["html-texte-listes","css-responsive"]'::jsonb, 14);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('js-variables', 'javascript', 'Fondamentaux', 'let, const et var', 'Déclarer une liaison, comprendre sa portée et exprimer si elle sera réassignée.', '["variable","let","const","var","scope","portée"]'::jsonb, 'Fondamental', '[{"type":"texte","titre":"Définition","contenu":"Une déclaration associe un nom à une valeur. const empêche de réassigner la liaison ; let autorise une réassignation. Les deux ont une portée de bloc. var suit des règles historiques de portée de fonction et de remontée qui favorisent les surprises."},{"type":"code","titre":"Syntaxe recommandée","langage":"JavaScript","contenu":"const utilisateur = { nom: \"Ada\" };\nlet tentatives = 0;\n\ntentatives += 1;\nutilisateur.nom = \"Grace\"; // autorisé : l’objet reste le même","legende":""},{"type":"comparaison","titre":"Conséquences pratiques","colonnes":["Mot-clé","Réassignable","Portée","Usage moderne"],"lignes":[["const","Non","Bloc","Choix par défaut"],["let","Oui","Bloc","Valeur qui doit changer"],["var","Oui","Fonction","Ancien code uniquement"]]},{"type":"alerte","variante":"erreur","titre":"Erreur fréquente","contenu":"const ne rend pas un objet immuable. Il interdit de remplacer la référence, mais ses propriétés peuvent encore changer."},{"type":"alerte","variante":"retenir","titre":"À retenir","contenu":"Utiliser const par défaut, puis let seulement lorsqu’une réassignation est nécessaire. Cela rend l’intention visible à la lecture."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Grammaire et types","url":"https://developer.mozilla.org/fr/docs/Web/JavaScript/Guide/Grammar_and_types"}]},{"type":"texte","titre":"Explication approfondie","contenu":"JavaScript orchestre des données et des actions. Séparez transformation pure, accès au monde extérieur et affichage pour savoir où chercher quand un résultat est faux."},{"type":"liste","titre":"Concepts à retenir","contenu":["données : cherchez où ce concept apparaît dans cette fiche avant de continuer.","fonctions : cherchez où ce concept apparaît dans cette fiche avant de continuer.","état : cherchez où ce concept apparaît dans cette fiche avant de continuer.","asynchronisme : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Calcul local","Fonction pure avec paramètres","Le résultat est facile à tester."],["Donnée distante","États chargement, succès et erreur","Le réseau est lent ou renvoie parfois une forme inattendue."],["Action répétée","Contrôler l’état et annuler si nécessaire","On évite résultats périmés et doubles soumissions."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"JavaScript","contenu":"function filtrerActifs(elements, terme) {\n  const recherche = terme.trim().toLowerCase();\n  return elements.filter((element) =>\n    element.actif && element.nom.toLowerCase().includes(recherche)\n  );\n}\n\nconsole.log(filtrerActifs([{ nom: \"Ada\", actif: true }], \"ad\"));","legende":"Exercice : ajoutez un cas vide, accentué et inactif."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « let, const et var », partez de un tableau de données venant d’une action. Produisez une transformation testable et observable. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un tableau vide, une valeur nulle ou une action répétée. La décision à justifier est la suivante : séparer donnée, transformation et effet extérieur."},{"type":"code","titre":"Mini-exercice spécifique : let, const et var","langage":"JavaScript","contenu":"const utilisateur = { nom: \"Ada\" };\nlet tentatives = 0;\n\ntentatives += 1;\nutilisateur.nom = \"Grace\"; // autorisé : l’objet reste le même","legende":"Leçon « let, const et var ». Entrée : un tableau de données venant d’une action. Sortie attendue : une transformation testable et observable. Cas limite : un tableau vide, une valeur nulle ou une action répétée. Décision : séparer donnée, transformation et effet extérieur."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « let, const et var » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Séparez la donnée, la transformation et l’effet visible. Cette séparation rend les erreurs plus faciles à localiser et les fonctions plus faciles à tester."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « let, const et var » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « let, const et var » et la reformuler avec vos mots.","concepts":["données","fonctions"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Calcul local","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[1]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[12]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[18]}]'::jsonb, '["js-types","js-fonctions","js-objets"]'::jsonb, 15);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('js-types', 'javascript', 'Fondamentaux', 'Types et typeof', 'Distinguer valeurs primitives, objets, null et conversions implicites.', '["string","number","boolean","undefined","null","symbol","bigint","typeof"]'::jsonb, 'Fondamental', '[{"type":"liste","titre":"Les types primitifs","contenu":["string : texte.","number : nombres entiers ou décimaux, avec NaN et Infinity.","boolean : true ou false.","undefined : absence de valeur généralement non initialisée.","null : absence choisie explicitement.","bigint : entiers arbitrairement grands.","symbol : identifiant unique."]},{"type":"code","titre":"Inspection","langage":"JavaScript","contenu":"typeof \"bonjour\";       // \"string\"\ntypeof 42;              // \"number\"\ntypeof true;            // \"boolean\"\ntypeof undefined;       // \"undefined\"\ntypeof 42n;             // \"bigint\"\ntypeof {};              // \"object\"\ntypeof null;            // \"object\" (bizarrerie historique)\nArray.isArray([]);       // true","legende":""},{"type":"texte","titre":"Valeur et référence","contenu":"Les primitives sont comparées par valeur. Les objets, fonctions et tableaux sont comparés par identité de référence : deux objets au contenu identique restent deux objets distincts."},{"type":"alerte","variante":"erreur","titre":"Piège historique","contenu":"typeof null renvoie \"object\" pour des raisons de compatibilité. Pour tester null, utiliser valeur === null. Pour un tableau, utiliser Array.isArray(valeur)."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Structures de données","url":"https://developer.mozilla.org/fr/docs/Web/JavaScript/Guide/Data_structures"}]},{"type":"texte","titre":"Explication approfondie","contenu":"JavaScript orchestre des données et des actions. Séparez transformation pure, accès au monde extérieur et affichage pour savoir où chercher quand un résultat est faux."},{"type":"liste","titre":"Concepts à retenir","contenu":["données : cherchez où ce concept apparaît dans cette fiche avant de continuer.","fonctions : cherchez où ce concept apparaît dans cette fiche avant de continuer.","état : cherchez où ce concept apparaît dans cette fiche avant de continuer.","asynchronisme : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Calcul local","Fonction pure avec paramètres","Le résultat est facile à tester."],["Donnée distante","États chargement, succès et erreur","Le réseau est lent ou renvoie parfois une forme inattendue."],["Action répétée","Contrôler l’état et annuler si nécessaire","On évite résultats périmés et doubles soumissions."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"JavaScript","contenu":"function filtrerActifs(elements, terme) {\n  const recherche = terme.trim().toLowerCase();\n  return elements.filter((element) =>\n    element.actif && element.nom.toLowerCase().includes(recherche)\n  );\n}\n\nconsole.log(filtrerActifs([{ nom: \"Ada\", actif: true }], \"ad\"));","legende":"Exercice : ajoutez un cas vide, accentué et inactif."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Types et typeof », partez de un tableau de données venant d’une action. Produisez une transformation testable et observable. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un tableau vide, une valeur nulle ou une action répétée. La décision à justifier est la suivante : séparer donnée, transformation et effet extérieur."},{"type":"code","titre":"Mini-exercice spécifique : Types et typeof","langage":"JavaScript","contenu":"typeof \"bonjour\";       // \"string\"\ntypeof 42;              // \"number\"\ntypeof true;            // \"boolean\"\ntypeof undefined;       // \"undefined\"\ntypeof 42n;             // \"bigint\"\ntypeof {};              // \"object\"\ntypeof null;            // \"object\" (bizarrerie historique)\nArray.isArray([]);       // true","legende":"Leçon « Types et typeof ». Entrée : un tableau de données venant d’une action. Sortie attendue : une transformation testable et observable. Cas limite : un tableau vide, une valeur nulle ou une action répétée. Décision : séparer donnée, transformation et effet extérieur."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Types et typeof » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Séparez la donnée, la transformation et l’effet visible. Cette séparation rend les erreurs plus faciles à localiser et les fonctions plus faciles à tester."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Types et typeof » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Types et typeof » et la reformuler avec vos mots.","concepts":["données","fonctions"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Calcul local","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[1]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["js-egalite","js-variables","js-objets"]'::jsonb, 16);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('js-egalite', 'javascript', 'Fondamentaux', '== ou ===', 'Comparer sans déclencher de conversions implicites difficiles à prévoir.', '["égalité","strict equality","coercition","double égal","triple égal"]'::jsonb, 'Fondamental', '[{"type":"comparaison","titre":"Différence","colonnes":["Opérateur","Conversion","Exemple","Conseil"],"lignes":[["===","Aucune conversion de type","\"5\" === 5 → false","À privilégier"],["==","Conversion selon des règles complexes","\"5\" == 5 → true","À reconnaître, rarement nécessaire"],["Object.is()","Comparaison SameValue","Object.is(NaN, NaN) → true","Cas spécialisés"]]},{"type":"code","titre":"Exemples révélateurs","langage":"JavaScript","contenu":"0 == false;          // true\n\"\" == false;         // true\nnull == undefined;   // true\n\n0 === false;         // false\n\"\" === false;        // false\nnull === undefined;  // false","legende":""},{"type":"texte","titre":"Conséquence pratique","contenu":"Avec ==, une comparaison apparemment innocente peut convertir booléens, chaînes et nombres. Avec ===, une différence de type est immédiatement fausse, ce qui rend le code et le debugging plus prévisibles."},{"type":"alerte","variante":"bonne-pratique","titre":"Recommandation","contenu":"Employer === et !== par défaut. Convertir explicitement lorsque le type doit changer : Number(valeur), String(valeur) ou Boolean(valeur)."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Égalité stricte","url":"https://developer.mozilla.org/fr/docs/Web/JavaScript/Reference/Operators/Strict_equality"}]},{"type":"texte","titre":"Explication approfondie","contenu":"JavaScript orchestre des données et des actions. Séparez transformation pure, accès au monde extérieur et affichage pour savoir où chercher quand un résultat est faux."},{"type":"liste","titre":"Concepts à retenir","contenu":["données : cherchez où ce concept apparaît dans cette fiche avant de continuer.","fonctions : cherchez où ce concept apparaît dans cette fiche avant de continuer.","état : cherchez où ce concept apparaît dans cette fiche avant de continuer.","asynchronisme : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Calcul local","Fonction pure avec paramètres","Le résultat est facile à tester."],["Donnée distante","États chargement, succès et erreur","Le réseau est lent ou renvoie parfois une forme inattendue."],["Action répétée","Contrôler l’état et annuler si nécessaire","On évite résultats périmés et doubles soumissions."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"JavaScript","contenu":"function filtrerActifs(elements, terme) {\n  const recherche = terme.trim().toLowerCase();\n  return elements.filter((element) =>\n    element.actif && element.nom.toLowerCase().includes(recherche)\n  );\n}\n\nconsole.log(filtrerActifs([{ nom: \"Ada\", actif: true }], \"ad\"));","legende":"Exercice : ajoutez un cas vide, accentué et inactif."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « == ou === », partez de un tableau de données venant d’une action. Produisez une transformation testable et observable. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un tableau vide, une valeur nulle ou une action répétée. La décision à justifier est la suivante : séparer donnée, transformation et effet extérieur."},{"type":"code","titre":"Mini-exercice spécifique : == ou ===","langage":"JavaScript","contenu":"0 == false;          // true\n\"\" == false;         // true\nnull == undefined;   // true\n\n0 === false;         // false\n\"\" === false;        // false\nnull === undefined;  // false","legende":"Leçon « == ou === ». Entrée : un tableau de données venant d’une action. Sortie attendue : une transformation testable et observable. Cas limite : un tableau vide, une valeur nulle ou une action répétée. Décision : séparer donnée, transformation et effet extérieur."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « == ou === » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Séparez la donnée, la transformation et l’effet visible. Cette séparation rend les erreurs plus faciles à localiser et les fonctions plus faciles à tester."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « == ou === » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « == ou === » et la reformuler avec vos mots.","concepts":["données","fonctions"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Calcul local","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[1]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["js-types","js-conditions"]'::jsonb, 17);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('js-conditions', 'javascript', 'Contrôle', 'Conditions et valeurs truthy/falsy', 'Exécuter une branche selon une expression booléenne sans confondre absence et valeur valide.', '["if","else","switch","ternaire","truthy","falsy","nullish"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Syntaxe","langage":"JavaScript","contenu":"if (score >= 80) {\n  niveau = \"avancé\";\n} else if (score >= 50) {\n  niveau = \"intermédiaire\";\n} else {\n  niveau = \"débutant\";\n}\n\nconst libelle = actif ? \"Activé\" : \"Désactivé\";","legende":""},{"type":"liste","titre":"Valeurs falsy","contenu":["false","0 et -0","0n","chaîne vide \"\"","null","undefined","NaN"]},{"type":"texte","titre":"?? contre ||","contenu":"L’opérateur || prend la valeur de droite dès que celle de gauche est falsy. ?? ne le fait que pour null ou undefined. Pour une valeur valide comme 0 ou \"\", ?? préserve généralement mieux l’intention."},{"type":"code","titre":"Valeur par défaut","langage":"JavaScript","contenu":"const quantite = 0;\n\nquantite || 10; // 10 : le zéro est remplacé\nquantite ?? 10; // 0 : le zéro est conservé","legende":""},{"type":"alerte","variante":"erreur","titre":"Erreur fréquente","contenu":"if (tableau.length) est correct pour tester un tableau non vide, mais if (valeur) n’est pas un test universel de présence : 0 peut être une donnée parfaitement valide."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Contrôle du flux","url":"https://developer.mozilla.org/fr/docs/Web/JavaScript/Guide/Control_flow_and_error_handling"}]},{"type":"texte","titre":"Explication approfondie","contenu":"JavaScript orchestre des données et des actions. Séparez transformation pure, accès au monde extérieur et affichage pour savoir où chercher quand un résultat est faux."},{"type":"liste","titre":"Concepts à retenir","contenu":["données : cherchez où ce concept apparaît dans cette fiche avant de continuer.","fonctions : cherchez où ce concept apparaît dans cette fiche avant de continuer.","état : cherchez où ce concept apparaît dans cette fiche avant de continuer.","asynchronisme : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Calcul local","Fonction pure avec paramètres","Le résultat est facile à tester."],["Donnée distante","États chargement, succès et erreur","Le réseau est lent ou renvoie parfois une forme inattendue."],["Action répétée","Contrôler l’état et annuler si nécessaire","On évite résultats périmés et doubles soumissions."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"JavaScript","contenu":"function filtrerActifs(elements, terme) {\n  const recherche = terme.trim().toLowerCase();\n  return elements.filter((element) =>\n    element.actif && element.nom.toLowerCase().includes(recherche)\n  );\n}\n\nconsole.log(filtrerActifs([{ nom: \"Ada\", actif: true }], \"ad\"));","legende":"Exercice : ajoutez un cas vide, accentué et inactif."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans une interface, la donnée passe souvent de l’utilisateur vers l’état, puis de l’état vers le rendu. Ne transmettez que ce qui est nécessaire : un composant enfant reçoit des props lisibles, une API reçoit un DTO validé et le navigateur ne reçoit jamais un secret."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir le besoin visible : texte, nombre, choix, fichier ou action. Un champ doit avoir un nom et une règle compréhensibles."},{"terme":"Valider","explication":"Vérifier présence, type, taille et format avant de modifier l’état. La validation du navigateur améliore le confort, mais le serveur doit la refaire."},{"terme":"Transformer","explication":"Convertir seulement quand le contrat le demande : trim pour un texte, Number pour un nombre explicite, FormData pour un fichier."},{"terme":"Transmettre","explication":"Envoyer un objet stable, avec Content-Type adapté et sans données privées inutiles. Une réponse doit avoir un état de chargement et un état d’erreur."},{"terme":"Stocker","explication":"Garder l’état local dans le composant si possible. localStorage ne convient pas aux secrets et une donnée serveur doit avoir une source de vérité."},{"terme":"Observer","explication":"Afficher un résultat, un message d’erreur et un état vide. Sans observation, on ne sait pas si la donnée a été reçue ou simplement ignorée."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["État local d’un formulaire","string / number / boolean validés","État React/Vue/Angular ou DOM","Ne pas stocker de secret dans le navigateur."],["Réponse d’API","DTO JSON validé à la frontière","fetch avec timeout et états UI","Ne jamais faire confiance au type annoncé par le serveur."],["Fichier envoyé","File puis FormData","multipart/form-data","Limiter taille, MIME et nom ; contrôler côté serveur."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Conditions et valeurs truthy/falsy », partez de un tableau de données venant d’une action. Produisez une transformation testable et observable. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un tableau vide, une valeur nulle ou une action répétée. La décision à justifier est la suivante : séparer donnée, transformation et effet extérieur."},{"type":"code","titre":"Mini-exercice spécifique : Conditions et valeurs truthy/falsy","langage":"JavaScript","contenu":"if (score >= 80) {\n  niveau = \"avancé\";\n} else if (score >= 50) {\n  niveau = \"intermédiaire\";\n} else {\n  niveau = \"débutant\";\n}\n\nconst libelle = actif ? \"Activé\" : \"Désactivé\";","legende":"Leçon « Conditions et valeurs truthy/falsy ». Entrée : un tableau de données venant d’une action. Sortie attendue : une transformation testable et observable. Cas limite : un tableau vide, une valeur nulle ou une action répétée. Décision : séparer donnée, transformation et effet extérieur."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Conditions et valeurs truthy/falsy » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Séparez la donnée, la transformation et l’effet visible. Cette séparation rend les erreurs plus faciles à localiser et les fonctions plus faciles à tester."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Conditions et valeurs truthy/falsy » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Conditions et valeurs truthy/falsy » et la reformuler avec vos mots.","concepts":["données","fonctions"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Calcul local","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"État local d’un formulaire","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Réponse d’API","sections":[12]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[18]}]'::jsonb, '["js-egalite","js-boucles","js-types"]'::jsonb, 18);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('js-boucles', 'javascript', 'Contrôle', 'for, for…of et forEach()', 'Choisir une itération selon le besoin de contrôle, les valeurs parcourues et l’asynchronisme.', '["for","for of","foreach","boucle","break","continue"]'::jsonb, 'Fondamental', '[{"type":"comparaison","titre":"Choix pratique","colonnes":["Forme","Force","Limite"],"lignes":[["for classique","Contrôle de l’index et du pas","Plus verbeux"],["for…of","Lit directement les valeurs","Index à obtenir séparément"],["forEach()","Exprime une action par élément","Pas de break ; attend mal async"],["map()","Construit un nouveau tableau","À éviter pour de simples effets de bord"]]},{"type":"code","titre":"Même besoin, trois formes","langage":"JavaScript","contenu":"for (let index = 0; index < noms.length; index += 1) {\n  console.log(index, noms[index]);\n}\n\nfor (const nom of noms) {\n  console.log(nom);\n}\n\nnoms.forEach((nom, index) => {\n  console.log(index, nom);\n});","legende":""},{"type":"alerte","variante":"attention","titre":"Asynchrone","contenu":"forEach() n’attend pas les Promises retournées par son callback. Pour traiter séquentiellement avec await, utiliser for…of dans une fonction async. Pour lancer en parallèle, construire des Promises puis utiliser Promise.all()."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Boucles et itération","url":"https://developer.mozilla.org/fr/docs/Web/JavaScript/Guide/Loops_and_iteration"}]},{"type":"texte","titre":"Explication approfondie","contenu":"JavaScript orchestre des données et des actions. Séparez transformation pure, accès au monde extérieur et affichage pour savoir où chercher quand un résultat est faux."},{"type":"liste","titre":"Concepts à retenir","contenu":["données : cherchez où ce concept apparaît dans cette fiche avant de continuer.","fonctions : cherchez où ce concept 