insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('shell-mkdir-touch', 'shell', 'Fichiers', 'mkdir et touch : créer une structure', 'Créer des dossiers et des fichiers vides pour préparer un exercice ou un projet.', '["mkdir","touch","parents","fichier"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Créer un mini-projet","langage":"Bash","contenu":"mkdir -p exercice-card/src exercice-card/public\ncd exercice-card\ntouch index.html styles.css README.md\ntouch src/app.js\nls -R","legende":"mkdir -p crée aussi les parents manquants ; touch crée un fichier vide ou met à jour sa date."},{"type":"decomposition","titre":"Options et arguments","elements":[{"terme":"mkdir","explication":"make directory : crée un dossier."},{"terme":"-p","explication":"crée les dossiers parents nécessaires sans échouer s’ils existent déjà."},{"terme":"src/app.js","explication":"chemin du fichier ; le dossier src doit exister avant touch."}]},{"type":"alerte","variante":"erreur","titre":"Erreur fréquente","contenu":"mkdir src/app crée un dossier app, pas un fichier app. Pour un fichier, utilisez touch ou un éditeur."},{"type":"alerte","variante":"attention","titre":"Attention","contenu":"touch ne crée pas les dossiers parents. mkdir -p src avant touch src/app.js."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"GNU Coreutils — mkdir","url":"https://www.gnu.org/software/coreutils/manual/html_node/mkdir-invocation.html"}]},{"type":"texte","titre":"Explication approfondie","contenu":"Le shell compose de petites commandes. Une commande fiable connaît son dossier, distingue sa sortie de ses erreurs et transmet un code retour à la CI."},{"type":"liste","titre":"Concepts à retenir","contenu":["chemin courant : cherchez où ce concept apparaît dans cette fiche avant de continuer.","sortie standard : cherchez où ce concept apparaît dans cette fiche avant de continuer.","pipeline : cherchez où ce concept apparaît dans cette fiche avant de continuer.","code retour : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Recherche","pwd, rg et sortie limitée","Le périmètre est visible."],["CI","Mode strict et codes retour","Une étape échoue au bon endroit."],["Chemin utilisateur","Quoter les variables","Les espaces ne cassent pas la commande."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"Bash","contenu":"#!/usr/bin/env bash\nset -euo pipefail\n\nracine=\"$1\"\nprintf \"Analyse de : %s\\n\" \"$racine\"\nrg -n --glob \"*.js\" \"TODO|FIXME\" \"$racine\" || true","legende":"Exercice : passez un chemin avec des espaces et comparez absence de résultat et erreur."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans les outils et la CI, les données arrivent souvent sous forme de chaînes : arguments, variables d’environnement, fichiers et sorties de commandes. Parsez-les au bord du système, échouez tôt et ne mettez jamais un secret dans une sortie ou un commit."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir arguments, variables obligatoires, fichiers attendus et code retour avant de lancer le script."},{"terme":"Valider","explication":"Vérifier que le chemin existe, que le nombre est réellement un nombre et que les variables sensibles ne sont pas vides."},{"terme":"Transformer","explication":"Parser une chaîne vers le type utile, normaliser un chemin avec l’outil adapté et convertir un JSON seulement après contrôle."},{"terme":"Transmettre","explication":"Utiliser stdout pour le résultat, stderr pour le diagnostic et un code retour non nul pour l’échec."},{"terme":"Stocker","explication":"Conserver les secrets dans le gestionnaire de secrets de la CI, jamais dans .env commité, un log ou une commande copiée."},{"terme":"Observer","explication":"Afficher le contexte non sensible, la durée et l’étape en échec pour rendre le script dépannable."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Commande locale","Arguments texte vérifiés","stdout, stderr et exit code","Éviter les chemins implicites et les variables non quotées."],["CI/CD","Variables injectées et types parsés","Logs masqués et artefact contrôlé","Utiliser secrets de plateforme et permissions minimales."],["Configuration serveur","JSON ou env validé au démarrage","Processus qui échoue tôt","Ne pas démarrer avec une configuration partiellement valide."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « mkdir et touch : créer une structure », partez de un argument ou une variable d’environnement texte. Produisez stdout, stderr et code retour cohérents. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un chemin avec espaces ou une variable manquante. La décision à justifier est la suivante : quoter les chemins et échouer tôt."},{"type":"code","titre":"Mini-exercice spécifique : mkdir et touch : créer une structure","langage":"Bash","contenu":"mkdir -p exercice-card/src exercice-card/public\ncd exercice-card\ntouch index.html styles.css README.md\ntouch src/app.js\nls -R","legende":"Leçon « mkdir et touch : créer une structure ». Entrée : un argument ou une variable d’environnement texte. Sortie attendue : stdout, stderr et code retour cohérents. Cas limite : un chemin avec espaces ou une variable manquante. Décision : quoter les chemins et échouer tôt."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « mkdir et touch : créer une structure » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Travaillez dans un dossier explicite, affichez les chemins avant les actions et préférez les commandes composables aux commandes opaques."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « mkdir et touch : créer une structure » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « mkdir et touch : créer une structure » et la reformuler avec vos mots.","concepts":["chemin courant","sortie standard"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Recherche","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Commande locale","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"CI/CD","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["shell-pwd-ls-cd","shell-cp-mv-rm"]'::jsonb, 74);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('shell-cp-mv-rm', 'shell', 'Fichiers', 'cp, mv et rm : copier, déplacer, supprimer', 'Manipuler des fichiers avec des commandes puissantes à utiliser après vérification.', '["cp","mv","rm","récursif","supprimer"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Exemples prudents","langage":"Bash","contenu":"cp index.html sauvegarde.html       # Copier\nmv sauvegarde.html archives/          # Déplacer / renommer\ncp -r src src-copie                 # Copier un dossier\nrm brouillon.txt                    # Supprimer un fichier\nrm -r dossier-temporaire             # Supprimer un dossier et son contenu","legende":""},{"type":"comparaison","titre":"Quelle commande choisir ?","colonnes":["Commande","Effet","Exemple"],"lignes":[["cp","Conserve la source et crée une copie","cp app.js app.bak.js"],["mv","Déplace ou renomme","mv ancien.js nouveau.js"],["rm","Supprime sans passer par une corbeille","rm fichier.txt"]]},{"type":"alerte","variante":"attention","titre":"Commande destructive","contenu":"rm ne demande pas toujours de confirmation et ne fournit pas de corbeille. Ne tapez jamais rm -rf sans avoir vérifié pwd et le chemin exact."},{"type":"alerte","variante":"bonne-pratique","titre":"Alternative plus sûre","contenu":"Utilisez rm -i pour demander une confirmation fichier par fichier et préférez un gestionnaire de fichiers pour les suppressions incertaines."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"GNU Coreutils — cp, mv, rm","url":"https://www.gnu.org/software/coreutils/manual/html_node/Basic-Operations.html"}]},{"type":"texte","titre":"Explication approfondie","contenu":"Le shell compose de petites commandes. Une commande fiable connaît son dossier, distingue sa sortie de ses erreurs et transmet un code retour à la CI."},{"type":"liste","titre":"Concepts à retenir","contenu":["chemin courant : cherchez où ce concept apparaît dans cette fiche avant de continuer.","sortie standard : cherchez où ce concept apparaît dans cette fiche avant de continuer.","pipeline : cherchez où ce concept apparaît dans cette fiche avant de continuer.","code retour : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Recherche","pwd, rg et sortie limitée","Le périmètre est visible."],["CI","Mode strict et codes retour","Une étape échoue au bon endroit."],["Chemin utilisateur","Quoter les variables","Les espaces ne cassent pas la commande."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"Bash","contenu":"#!/usr/bin/env bash\nset -euo pipefail\n\nracine=\"$1\"\nprintf \"Analyse de : %s\\n\" \"$racine\"\nrg -n --glob \"*.js\" \"TODO|FIXME\" \"$racine\" || true","legende":"Exercice : passez un chemin avec des espaces et comparez absence de résultat et erreur."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans les outils et la CI, les données arrivent souvent sous forme de chaînes : arguments, variables d’environnement, fichiers et sorties de commandes. Parsez-les au bord du système, échouez tôt et ne mettez jamais un secret dans une sortie ou un commit."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir arguments, variables obligatoires, fichiers attendus et code retour avant de lancer le script."},{"terme":"Valider","explication":"Vérifier que le chemin existe, que le nombre est réellement un nombre et que les variables sensibles ne sont pas vides."},{"terme":"Transformer","explication":"Parser une chaîne vers le type utile, normaliser un chemin avec l’outil adapté et convertir un JSON seulement après contrôle."},{"terme":"Transmettre","explication":"Utiliser stdout pour le résultat, stderr pour le diagnostic et un code retour non nul pour l’échec."},{"terme":"Stocker","explication":"Conserver les secrets dans le gestionnaire de secrets de la CI, jamais dans .env commité, un log ou une commande copiée."},{"terme":"Observer","explication":"Afficher le contexte non sensible, la durée et l’étape en échec pour rendre le script dépannable."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Commande locale","Arguments texte vérifiés","stdout, stderr et exit code","Éviter les chemins implicites et les variables non quotées."],["CI/CD","Variables injectées et types parsés","Logs masqués et artefact contrôlé","Utiliser secrets de plateforme et permissions minimales."],["Configuration serveur","JSON ou env validé au démarrage","Processus qui échoue tôt","Ne pas démarrer avec une configuration partiellement valide."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « cp, mv et rm : copier, déplacer, supprimer », partez de un argument ou une variable d’environnement texte. Produisez stdout, stderr et code retour cohérents. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un chemin avec espaces ou une variable manquante. La décision à justifier est la suivante : quoter les chemins et échouer tôt."},{"type":"code","titre":"Mini-exercice spécifique : cp, mv et rm : copier, déplacer, supprimer","langage":"Bash","contenu":"cp index.html sauvegarde.html       # Copier\nmv sauvegarde.html archives/          # Déplacer / renommer\ncp -r src src-copie                 # Copier un dossier\nrm brouillon.txt                    # Supprimer un fichier\nrm -r dossier-temporaire             # Supprimer un dossier et son contenu","legende":"Leçon « cp, mv et rm : copier, déplacer, supprimer ». Entrée : un argument ou une variable d’environnement texte. Sortie attendue : stdout, stderr et code retour cohérents. Cas limite : un chemin avec espaces ou une variable manquante. Décision : quoter les chemins et échouer tôt."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « cp, mv et rm : copier, déplacer, supprimer » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Travaillez dans un dossier explicite, affichez les chemins avant les actions et préférez les commandes composables aux commandes opaques."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « cp, mv et rm : copier, déplacer, supprimer » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « cp, mv et rm : copier, déplacer, supprimer » et la reformuler avec vos mots.","concepts":["chemin courant","sortie standard"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Recherche","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Commande locale","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"CI/CD","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["shell-pwd-ls-cd","shell-mkdir-touch","shell-permissions"]'::jsonb, 75);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('shell-cat-less-head-tail', 'shell', 'Lecture', 'cat, less, head et tail : lire sans ouvrir un éditeur', 'Inspecter rapidement un fichier ou suivre un journal de serveur directement dans le terminal.', '["cat","less","head","tail","logs"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Lire et suivre","langage":"Bash","contenu":"cat package.json              # Afficher tout le fichier\nless package.json             # Lire avec défilement\nhead -n 20 server.log         # Voir les 20 premières lignes\ntail -n 20 server.log          # Voir les 20 dernières lignes\ntail -f server.log            # Suivre les nouvelles lignes en direct","legende":""},{"type":"texte","titre":"Quand utiliser quoi","contenu":"cat convient aux petits fichiers. less évite de remplir le terminal pour un gros fichier : appuyez sur q pour quitter. tail -f est utile pour observer les logs pendant qu’un serveur tourne ; Ctrl+C arrête le suivi."},{"type":"alerte","variante":"erreur","titre":"Fichier introuvable","contenu":"Un chemin relatif est calculé depuis le dossier courant. Vérifiez pwd, puis ls, puis écrivez le chemin correctement."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"man7 — cat, less et tail","url":"https://man7.org/linux/man-pages/man1/tail.1.html"}]},{"type":"texte","titre":"Explication approfondie","contenu":"Le shell compose de petites commandes. Une commande fiable connaît son dossier, distingue sa sortie de ses erreurs et transmet un code retour à la CI."},{"type":"liste","titre":"Concepts à retenir","contenu":["chemin courant : cherchez où ce concept apparaît dans cette fiche avant de continuer.","sortie standard : cherchez où ce concept apparaît dans cette fiche avant de continuer.","pipeline : cherchez où ce concept apparaît dans cette fiche avant de continuer.","code retour : cherchez où ce concept 